function QuenchOilFilterMaker.init() QuenchOilFilterMaker.ironStock=14; QuenchOilFilterMaker.bronzeStock=12; QuenchOilFilterMaker.woodStock=12; QuenchOilFilterMaker.leatherStock=8; QuenchOilFilterMaker.silverStock=8; QuenchOilFilterMaker.goldStock=6; QuenchOilFilterMaker.jewelStock=4; QuenchOilFilterMaker.pearlStock=4; QuenchOilFilterMaker.productStock={}; QuenchOilFilterMaker.buildings={}; QuenchOilFilterMaker.maker=nil; QuenchOilFilterMaker.activeMaking={}; QuenchOilFilterMaker.totalProducts=0; QuenchOilFilterMaker.dayTimer=0; print("[QuenchOilFilterMaker] Royal Quench Oil Filter Maker System initialized (6 products, 4 buildings)") end
function QuenchOilFilterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuenchOilFilterMaker.maker={name=n or ("Filtrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Filtrar najet: %s (spretnost: %d)",QuenchOilFilterMaker.maker.name,s),"success") end; return true end
function QuenchOilFilterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuenchOilFilterMaker.build(id) local ok,e=QuenchOilFilterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuenchOilFilterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuenchOilFilterMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuenchOilFilterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuenchOilFilterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuenchOilFilterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuenchOilFilterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuenchOilFilterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuenchOilFilterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuenchOilFilterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuenchOilFilterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuenchOilFilterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuenchOilFilterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuenchOilFilterMaker.buildings==0 then return false,"Potrebna filtna delavnica" end; if not QuenchOilFilterMaker.maker then return false,"Potreben filtrar" end; return true end
function QuenchOilFilterMaker.make(pt,qty) qty=qty or 1; local ok,e=QuenchOilFilterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuenchOilFilterMaker.ironStock=QuenchOilFilterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuenchOilFilterMaker.bronzeStock=QuenchOilFilterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuenchOilFilterMaker.woodStock=QuenchOilFilterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuenchOilFilterMaker.leatherStock=QuenchOilFilterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuenchOilFilterMaker.silverStock=QuenchOilFilterMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuenchOilFilterMaker.goldStock=QuenchOilFilterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuenchOilFilterMaker.jewelStock=QuenchOilFilterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuenchOilFilterMaker.pearlStock=QuenchOilFilterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuenchOilFilterMaker.maker then t=math.max(1,t-math.floor(QuenchOilFilterMaker.maker.skill/13)) end; table.insert(QuenchOilFilterMaker.activeMaking,{id="quencholfilter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuenchOilFilterMaker.completeMaking(m) local q=1.0+(QuenchOilFilterMaker.getQualityBonus()/100); if QuenchOilFilterMaker.maker then q=q+(QuenchOilFilterMaker.maker.skill/140) end; q=math.min(2.5,q); QuenchOilFilterMaker.productStock[m.productType]=(QuenchOilFilterMaker.productStock[m.productType] or 0)+m.quantity; QuenchOilFilterMaker.totalProducts=QuenchOilFilterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuenchOilFilterMaker.maker then QuenchOilFilterMaker.maker.itemsMade=QuenchOilFilterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuenchOilFilterMaker.maker.skill=math.min(100,QuenchOilFilterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Filter izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quencholfilter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuenchOilFilterMaker.update(dt) if not _G.state then return end; QuenchOilFilterMaker.dayTimer=QuenchOilFilterMaker.dayTimer+dt; if QuenchOilFilterMaker.dayTimer>=30 then QuenchOilFilterMaker.dayTimer=0; for i=#QuenchOilFilterMaker.activeMaking,1,-1 do local m=QuenchOilFilterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuenchOilFilterMaker.completeMaking(m); table.remove(QuenchOilFilterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuenchOilFilterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuenchOilFilterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuenchOilFilterMaker.getStats() return {ironStock=QuenchOilFilterMaker.ironStock,bronzeStock=QuenchOilFilterMaker.bronzeStock,woodStock=QuenchOilFilterMaker.woodStock,leatherStock=QuenchOilFilterMaker.leatherStock,silverStock=QuenchOilFilterMaker.silverStock,goldStock=QuenchOilFilterMaker.goldStock,jewelStock=QuenchOilFilterMaker.jewelStock,pearlStock=QuenchOilFilterMaker.pearlStock,productStock=QuenchOilFilterMaker.productStock,numBuildings=#QuenchOilFilterMaker.buildings,hasMaker=QuenchOilFilterMaker.maker~=nil,makerName=QuenchOilFilterMaker.maker and QuenchOilFilterMaker.maker.name or "—",makerSkill=QuenchOilFilterMaker.maker and QuenchOilFilterMaker.maker.skill or 0,activeMaking=#QuenchOilFilterMaker.activeMaking,totalProducts=QuenchOilFilterMaker.totalProducts} end
return QuenchOilFilterMaker
